using System;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Threading;using System.Threading.Tasks;using BalatROM.Setup;
[DataContract] public sealed class SetupResult {
 [DataMember] public string status,installed_executable,installer_sha256,scope;
 [DataMember] public int cached_component_copies,network_requests,busy_gate_checks;
 [DataMember] public bool manifest_verified,offline_reopen,original_cache_unchanged;
 [DataMember] public double wall_seconds;
}
class NativeSetupQA {
 static byte[] Resource(Assembly a,string name){using(var stream=a.GetManifestResourceStream(name)){if(stream==null)throw new Exception("Missing embedded resource "+name);using(var memory=new MemoryStream()){stream.CopyTo(memory);return memory.ToArray();}}}
 static void Need(bool value,string message){if(!value)throw new Exception(message);}
 static int Gate(Assembly assembly){
  var type=assembly.GetType("SetupRunState",true);object gate=Activator.CreateInstance(type,true);Func<object,bool> start=o=>(bool)type.GetMethod("TryStart").Invoke(o,null);Action<object,bool,bool> finish=(o,s,c)=>type.GetMethod("FinishAfterTeardown").Invoke(o,new object[]{s,c});
  Need(start(gate),"first click refused");Need((bool)type.GetProperty("IsRunning").GetValue(gate),"busy state not immediate");Need(!start(gate),"duplicate click admitted");int generation=(int)type.GetProperty("Generation").GetValue(gate);finish(gate,false,false);Need(!(bool)type.GetMethod("CanApplyProgress").Invoke(gate,new object[]{generation}),"stale progress survived teardown");Need(start(gate),"safe retry refused");finish(gate,true,false);Need(!start(gate),"second launch admitted after success");object race=Activator.CreateInstance(type,true);int admitted=0;Parallel.For(0,32,i=>{if(start(race))Interlocked.Increment(ref admitted);});Need(admitted==1,"parallel duplicate activation");finish(race,false,true);Need(!start(race),"closing run reopened");return 8;
 }
 static async Task Run(string[] args){
  string output=Path.GetFullPath(args[0]),cache=Path.GetFullPath(args[1]),expected=args[2];Need(!Directory.Exists(output),"QA output already exists; inspect before another run");var began=DateTime.UtcNow;var assembly=typeof(Engine).Assembly;Need(Engine.HashFile(assembly.Location)==expected,"Installer transfer checksum mismatch");int gates=Gate(assembly);var config=Engine.Json<Config>(Resource(assembly,"Config"));byte[] payload=Resource(assembly,"Payload"),manifest=Resource(assembly,"Manifest");int copies=0;var original=config.Components.ToDictionary(c=>c.Sha256,c=>Engine.HashFile(Path.Combine(cache,c.Sha256+".zip")));
  Func<Component,string,CancellationToken,Action<ProgressInfo>,Task> source=(c,path,cancel,progress)=>{cancel.ThrowIfCancellationRequested();string file=Path.Combine(cache,c.Sha256+".zip");Need(new FileInfo(file).Length==c.Bytes&&Engine.HashFile(file)==c.Sha256,"Cached official component differs");File.Copy(file,path,false);copies++;return Task.CompletedTask;};
  Action<ProgressInfo> report=p=>Console.WriteLine(p.Message);string installed=await Engine.Install(output,config,payload,manifest,CancellationToken.None,report,source);Need(copies==4,"Expected four verified cached components");Need(Engine.Verify(Path.GetDirectoryName(installed),manifest,config.PackageManifestSha256,CancellationToken.None),"Actual installed app manifest mismatch");int repeated=0;string again=await Engine.Install(output,config,payload,manifest,CancellationToken.None,report,(a,b,c,d)=>{repeated++;throw new Exception("Offline reopen must not request a download");});Need(repeated==0&&again==installed,"Offline reopen mismatch");Need(config.Components.All(c=>Engine.HashFile(Path.Combine(cache,c.Sha256+".zip"))==original[c.Sha256]),"Original download cache changed");
  var result=new SetupResult{status="PASS_NATIVE_WINDOWS_EXACT_INSTALLER_ENGINE_PACKAGE_AND_BUSY_GATE",installed_executable=installed,installer_sha256=expected,cached_component_copies=copies,network_requests=0,busy_gate_checks=gates,manifest_verified=true,offline_reopen=true,original_cache_unchanged=true,wall_seconds=(DateTime.UtcNow-began).TotalSeconds,scope="Exact installer assembly/resources and production setup gate; no Main/WinForms window launched, no personal GUI acceptance"};using(var stream=File.Create(Path.Combine(output,"NATIVE-INSTALLER-RESULT.json")))new DataContractJsonSerializer(typeof(SetupResult)).WriteObject(stream,result);Console.WriteLine("NATIVE_INSTALLER_PASS");
 }
 static int Main(string[] args){try{Run(args).GetAwaiter().GetResult();return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
